const CL={international:'International',controlled:'Controlled',uncontrolled:'Uncontrolled',heliport:'Heliport',seaplane_base:'Seaplane base',balloonport:'Balloonport'};const cb=a=>`<span class="b cat-${a.cat}" title="${E(a.catwhy)}">${CL[a.cat]}${a.inferred?' (inferred)':''}</span>`;const warr=d=>d==null||d==='VRB'?'':`<span class=warr style="transform:rotate(${(+d+180)%360}deg)"><svg viewBox="0 0 24 24" fill=none stroke="#1446D6" stroke-width=2 stroke-linecap=round><path d="M12 20V4M6 10l6-6 6 6"/></svg></span>`;const fcModel=c=>{if(!c||c.visibility==null)return null;const sm=c.visibility/1609.34;return sm<1?'LIFR':sm<3?'IFR':sm<=5?'MVFR':'VFR'};
