function metVis(w){if(/CAVOK/.test(w.rawOb))return 10000;const m=/ (\d{4}) /.exec(w.rawOb.replace(/Q\d{4}.*/,''));if(m)return +m[1];if(w.visib==='6+')return 10000;const v=parseFloat(w.visib);return isNaN(v)?null:v*1609}
